#pragma once

#include <string>

/// <summary>
/// A class to represent a proof ID.
/// A proof ID is a unique identifier for a proof.
/// Used to re-authenticate a user, thoughout the applications lifecycle.
/// The proof ID is generated by the users email and a random number.
/// </summary>
class ProofID
{
private:
	std::string m_ProofID;
public:
	// Default constructors
	ProofID() { }
	ProofID(const std::string& proofID) : m_ProofID(proofID) { }
	~ProofID() { m_ProofID = ""; }

	// Getters
	std::string GetProofID() const { return m_ProofID; }

	// Check if two ProofID's are equal
	bool operator==(const ProofID& other) const { return m_ProofID == other.m_ProofID; }
};